import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, join, normalize, sep } from "node:path";
import { GetObjectCommand, PutObjectCommand, S3Client } from "@aws-sdk/client-s3";
import type { Env } from "../config/config.js";

/**
 * Binary blobs (zone rasters, NDVI images) in object storage when S3_BUCKET is set, on local disk under UPLOADS_DIR
 * otherwise. PostgreSQL keeps only the key. Keys are generated by the app, never taken from a request.
 */
export class BlobStore {
  private readonly s3: S3Client | null;

  constructor(private readonly env: Pick<Env, "S3_BUCKET" | "AWS_REGION" | "UPLOADS_DIR">) {
    this.s3 = env.S3_BUCKET ? new S3Client({ region: env.AWS_REGION }) : null;
  }

  async put(key: string, bytes: Uint8Array, contentType = "application/octet-stream"): Promise<void> {
    if (this.s3) {
      await this.s3.send(
        new PutObjectCommand({ Bucket: this.env.S3_BUCKET, Key: key, Body: bytes, ContentType: contentType }),
      );
      return;
    }
    const path = this.path(key);
    await mkdir(dirname(path), { recursive: true });
    await writeFile(path, bytes);
  }

  /** The bytes, or null when the object does not exist. */
  async get(key: string): Promise<Uint8Array | null> {
    try {
      if (this.s3) {
        const r = await this.s3.send(new GetObjectCommand({ Bucket: this.env.S3_BUCKET, Key: key }));
        return r.Body ? await r.Body.transformToByteArray() : null;
      }
      return new Uint8Array(await readFile(this.path(key)));
    } catch (e) {
      const err = e as { code?: string; name?: string };
      if (err.code === "ENOENT" || err.name === "NoSuchKey") return null;
      throw e;
    }
  }

  private path(key: string): string {
    const full = normalize(join(this.env.UPLOADS_DIR, key));
    if (!full.startsWith(normalize(this.env.UPLOADS_DIR) + sep)) throw new Error("bad blob key");
    return full;
  }
}
